<?php require 'config.php';$u=require_login();$q=mb_substr(trim($_GET['q']??''),0,100);$cat=mb_substr(trim($_GET['category']??''),0,80);page_start('Learning library',$u);heading('CURIOSITY LOOKS GOOD ON YOU','One lesson closer.','Explore trusted learning materials. Mark what you finish and watch your progress grow.'); ?>
<form class="search" method="get"><input aria-label="Search resources" name="q" placeholder="Search the library…" value="<?=e($q)?>"><select aria-label="Category" name="category"><option value="">All categories</option><?php foreach(rows('SELECT DISTINCT category FROM resources ORDER BY category') as $c)echo '<option '.($cat===$c['category']?'selected':'').' value="'.e($c['category']).'">'.e($c['category']).'</option>';?></select><button class="button">Search</button></form>
<div class="grid"><?php $resources=rows('SELECT r.*, (SELECT COUNT(*) FROM progress p WHERE p.resource_id=r.id AND p.user_id=?) done FROM resources r WHERE (title LIKE ? OR description LIKE ?) AND (?=\'\' OR category=?) ORDER BY id',[$u['id'],'%'.$q.'%','%'.$q.'%',$cat,$cat]);foreach($resources as $r):?><article class="card"><span class="badge"><?=e($r['category'])?></span><h2><?=e($r['title'])?></h2><p><?=e($r['description'])?></p><div class="inline"><a class="button secondary" href="<?=e($r['url'])?>" target="_blank" rel="noopener noreferrer">Open resource ↗</a><form method="post" action="action.php"><?php csrf();?><input type="hidden" name="action" value="<?=$r['done']?'uncomplete':'complete'?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="ghost"><?=$r['done']?'✓ Completed · Undo':'Mark completed'?></button></form></div></article><?php endforeach;if(!$resources)echo '<p>No resources match. Try another search.</p>';?></div><?php page_end(); ?>
